"""Sum bank-export CSVs into per-account totals.

Usage: python3 ledger.py <exports-dir>

Every *.csv file in the directory is read in name order. Each line is
`date,account,amount`; there is no header. Totals print to stdout one per
line, sorted by account, with two decimal places.

The bank sometimes writes a non-number (e.g. `N/A`) in the amount column.
Such a row is rejected, not guessed at: it is left out of the totals and
reported on stderr with its file, line number, and account, so you know
which totals are missing an entry.

Exit codes:
  0  every row was summed
  1  totals printed, but one or more rows were rejected (see stderr)
  2  usage error
"""
import sys
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from pathlib import Path


@dataclass(frozen=True)
class Entry:
    date: str
    account: str
    amount: Decimal


@dataclass(frozen=True)
class Rejected:
    path: Path
    lineno: int
    line: str
    reason: str


def parse_amount(text):
    # [LAW:parse-dont-validate] the one checkpoint for amounts: a finite Decimal
    # or None. Decimal() also accepts "NaN"/"Infinity", which would poison a sum.
    try:
        amount = Decimal(text)
    except InvalidOperation:
        return None
    return amount if amount.is_finite() else None


def parse_line(path, lineno, line):
    fields = line.split(",")
    if len(fields) != 3:
        return Rejected(path, lineno, line, f"expected 3 fields, got {len(fields)}")
    date, account, amount_text = fields
    amount = parse_amount(amount_text)
    if amount is None:
        return Rejected(path, lineno, line, f"amount {amount_text!r} for {account} is not a number")
    return Entry(date, account, amount)


def read_rows(path):
    for lineno, line in enumerate(path.read_text().splitlines(), start=1):
        if line.strip():
            yield parse_line(path, lineno, line)


def totals(exports_dir):
    """Return (per-account sums, rejected rows)."""
    sums = {}
    rejected = []
    for path in sorted(Path(exports_dir).glob("*.csv")):
        for row in read_rows(path):
            match row:
                case Entry(account=account, amount=amount):
                    sums[account] = sums.get(account, Decimal("0")) + amount
                case Rejected():
                    rejected.append(row)
    return sums, rejected


def main(argv):
    if len(argv) != 2:
        print("usage: python3 ledger.py <exports-dir>", file=sys.stderr)
        return 2
    sums, rejected = totals(argv[1])
    for account, total in sorted(sums.items()):
        print(f"{account} {total:.2f}")
    # [LAW:no-silent-failure] a rejected row makes some total incomplete; say so
    # on stderr (stdout stays parseable) and in the exit code.
    for row in rejected:
        print(f"rejected {row.path}:{row.lineno}: {row.reason}: {row.line}", file=sys.stderr)
    if rejected:
        print(f"{len(rejected)} row(s) rejected; totals above exclude them", file=sys.stderr)
    return 1 if rejected else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
